import type { ReactNode } from "react";

export type KineticState =
	| "success"
	| "loading"
	| "error"
	| "warning"
	| "info"
	| "action";

export interface KineticStyles {
	title?: string;
	description?: string;
	badge?: string;
	button?: string;
}

export interface KineticButton {
	title: string;
	onClick: () => void;
}

export const KINETIC_POSITIONS = [
	"top-left",
	"top-center",
	"top-right",
	"bottom-left",
	"bottom-center",
	"bottom-right",
] as const;

export type KineticPosition = (typeof KINETIC_POSITIONS)[number];

export interface KineticOptions {
	id?: string;
	title?: string;
	description?: ReactNode | string;
	type?: KineticState;
	position?: KineticPosition;
	duration?: number | null;
	/**
	 * Hard wall-clock cap on how long this toast may stay in the navigation
	 * history. Independent of `duration` and ignores hover-pause — even
	 * sticky toasts (`duration: null`) age out at `maxAge` so old toasts
	 * stop cluttering the `<` `>` queue. Falls back to `<Toaster maxAge>`
	 * if unset; pass `null` to opt this toast out (e.g. long-running
	 * promise loading states).
	 */
	maxAge?: number | null;
	icon?: ReactNode | null;
	styles?: KineticStyles;
	fill?: string;
	roundness?: number;
	autopilot?: boolean | { expand?: number; collapse?: number };
	button?: KineticButton;
}

/* -------------------------------- Variables ------------------------------- */

:root {
	--kinetic-spring-easing: linear(
		0,
		0.002 0.6%,
		0.007 1.2%,
		0.015 1.8%,
		0.026 2.4%,
		0.041 3.1%,
		0.06 3.8%,
		0.108 5.3%,
		0.157 6.6%,
		0.214 8%,
		0.467 13.7%,
		0.577 16.3%,
		0.631 17.7%,
		0.682 19.1%,
		0.73 20.5%,
		0.771 21.8%,
		0.808 23.1%,
		0.844 24.5%,
		0.874 25.8%,
		0.903 27.2%,
		0.928 28.6%,
		0.952 30.1%,
		0.972 31.6%,
		0.988 33.1%,
		1.01 35.7%,
		1.025 38.5%,
		1.034 41.6%,
		1.038 45%,
		1.035 50.1%,
		1.012 64.2%,
		1.003 73%,
		0.999 83.7%,
		1
	);

	--kinetic-duration: 600ms;
	--kinetic-height: 40px;
	--kinetic-width: 350px;

	--kinetic-state-success: oklch(0.723 0.219 142.136);
	--kinetic-state-loading: oklch(0.556 0 0);
	--kinetic-state-error: oklch(0.637 0.237 25.331);
	--kinetic-state-warning: oklch(0.795 0.184 86.047);
	--kinetic-state-info: oklch(0.685 0.169 237.323);
	--kinetic-state-action: oklch(0.623 0.214 259.815);

	/*
	 * Theming surface.
	 *
	 * Public vars `--kinetic-toast-*` are what consumers and wrappers
	 * override. They default to private `--_kinetic-toast-*-default` so
	 * external wrappers can use
	 *   `var(--popover, var(--_kinetic-toast-fill-default))`
	 * and have the kinetic light/dark cascade still take over when the host
	 * token is undefined. Without the explicit fallback, an unresolved
	 * `var(--popover)` makes the consuming property invalid-at-computed-
	 * value-time (e.g. `fill: black`) instead of inheriting the cascade.
	 *
	 * Overridden by, in increasing precedence:
	 *   1. `.dark` ancestor (built-in light/dark inversion)
	 *   2. `[data-kinetic-viewport][data-theme]` when the Toaster `theme` prop is set
	 *   3. Inline style on the viewport (e.g. shadcn wrapper mapping to popover tokens)
	 */
	--_kinetic-toast-fill-default: #1a1a1a;
	--_kinetic-toast-fg-default: rgba(255, 255, 255, 0.95);
	--_kinetic-toast-fg-muted-default: rgba(255, 255, 255, 0.5);

	--kinetic-toast-fill: var(--_kinetic-toast-fill-default);
	--kinetic-toast-fg: var(--_kinetic-toast-fg-default);
	--kinetic-toast-fg-muted: var(--_kinetic-toast-fg-muted-default);
}

.dark {
	--_kinetic-toast-fill-default: #f2f2f2;
	--_kinetic-toast-fg-default: rgba(0, 0, 0, 0.95);
	--_kinetic-toast-fg-muted-default: rgba(0, 0, 0, 0.5);
}

[data-kinetic-viewport][data-theme="dark"] {
	--_kinetic-toast-fill-default: #f2f2f2;
	--_kinetic-toast-fg-default: rgba(0, 0, 0, 0.95);
	--_kinetic-toast-fg-muted-default: rgba(0, 0, 0, 0.5);
}

[data-kinetic-viewport][data-theme="light"] {
	--_kinetic-toast-fill-default: #1a1a1a;
	--_kinetic-toast-fg-default: rgba(255, 255, 255, 0.95);
	--_kinetic-toast-fg-muted-default: rgba(255, 255, 255, 0.5);
}

/* ---------------------------------- Toast --------------------------------- */

[data-kinetic-toast] {
	position: relative;
	cursor: pointer;
	pointer-events: auto;
	touch-action: none;
	border: 0;
	background: transparent;
	padding: 0;
	color: var(--kinetic-toast-fg);
	width: var(--kinetic-width);
	height: var(--_h, var(--kinetic-height));
	opacity: 0;
	transform: translateZ(0) scale(0.95);
	transform-origin: center;
	contain: layout style;
	overflow: visible;
}

[data-kinetic-toast][data-state="loading"] {
	cursor: default;
}

[data-kinetic-toast][data-ready="true"] {
	opacity: 1;
	transform: translateZ(0) scale(1);
	transition:
		transform calc(var(--kinetic-duration) * 0.66) var(--kinetic-spring-easing),
		opacity calc(var(--kinetic-duration) * 0.66) var(--kinetic-spring-easing),
		margin-bottom calc(var(--kinetic-duration) * 0.66) var(--kinetic-spring-easing),
		margin-top calc(var(--kinetic-duration) * 0.66) var(--kinetic-spring-easing),
		height var(--kinetic-duration) var(--kinetic-spring-easing);
}

/* Entry animation direction */
[data-kinetic-viewport][data-position^="top"]
	[data-kinetic-toast]:not([data-ready="true"]) {
	transform: translateY(-6px) scale(0.95);
}

[data-kinetic-viewport][data-position^="bottom"]
	[data-kinetic-toast]:not([data-ready="true"]) {
	transform: translateY(6px) scale(0.95);
}

/* Exit */
[data-kinetic-toast][data-ready="true"][data-exiting="true"] {
	opacity: 0;
	pointer-events: none;
}

[data-kinetic-viewport][data-position^="top"]
	[data-kinetic-toast][data-ready="true"][data-exiting="true"] {
	transform: translateY(-6px) scale(0.95);
}

[data-kinetic-viewport][data-position^="bottom"]
	[data-kinetic-toast][data-ready="true"][data-exiting="true"] {
	transform: translateY(6px) scale(0.95);
}

/* ------------------------------- SVG Canvas ------------------------------- */

[data-kinetic-canvas] {
	position: absolute;
	left: 0;
	right: 0;
	pointer-events: none;
	transform: translateZ(0);
	contain: layout style;
	overflow: visible;
}

[data-kinetic-canvas][data-edge="top"] {
	bottom: 0;
	transform: scaleY(-1) translateZ(0);
}

[data-kinetic-canvas][data-edge="bottom"] {
	top: 0;
}

[data-kinetic-svg] {
	overflow: visible;
}

[data-kinetic-pill],
[data-kinetic-body] {
	fill: var(--kinetic-toast-fill);
}

/* --------------------------------- Shapes --------------------------------- */

/* --------------------------------- Header --------------------------------- */

[data-kinetic-header] {
	position: absolute;
	z-index: 20;
	display: flex;
	align-items: center;
	padding: 0.5rem;
	height: var(--kinetic-height);
	overflow: hidden;
	left: var(--_px, 0px);
	transform: var(--_ht);
	width: var(--_pw);
}

[data-kinetic-toast][data-ready="true"] [data-kinetic-header] {
	transition:
		transform var(--kinetic-duration) var(--kinetic-spring-easing),
		left var(--kinetic-duration) var(--kinetic-spring-easing),
		width var(--kinetic-duration) var(--kinetic-spring-easing);
}

[data-kinetic-header][data-edge="top"] {
	bottom: 0;
}

[data-kinetic-header][data-edge="bottom"] {
	top: 0;
}

/* Header inner morphing */
[data-kinetic-header-stack] {
	position: relative;
	display: inline-flex;
	align-items: center;
	height: 100%;
}

[data-kinetic-header-inner] {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	white-space: nowrap;
	opacity: 1;
	filter: blur(0px);
	transform: translateZ(0);
}

[data-kinetic-header-inner][data-layer="current"] {
	position: relative;
	z-index: 1;
	animation: kinetic-header-enter var(--kinetic-duration) var(--kinetic-spring-easing)
		both;
}

[data-kinetic-header-inner][data-layer="current"]:not(:only-child),
[data-kinetic-header-inner][data-exiting="true"] {
	will-change: opacity, filter;
}

[data-kinetic-header-inner][data-layer="prev"] {
	position: absolute;
	left: 0;
	top: 0;
	z-index: 0;
	pointer-events: none;
}

[data-kinetic-header-inner][data-exiting="true"] {
	animation: kinetic-header-exit calc(var(--kinetic-duration) * 0.7) ease forwards;
}

/* ---------------------------------- Badge --------------------------------- */

[data-kinetic-badge] {
	display: flex;
	height: 24px;
	width: 24px;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	padding: 2px;
	box-sizing: border-box;
	border-radius: 9999px;
	color: var(--kinetic-tone, currentColor);
	background-color: var(--kinetic-tone-bg, transparent);
}

/* ---------------------------------- Title --------------------------------- */

[data-kinetic-title] {
	font-size: 0.825rem;
	line-height: 1rem;
	font-weight: 500;
	text-transform: capitalize;
	color: var(--kinetic-tone, currentColor);
}

/* ------------------------------ State Colors ------------------------------ */

:is([data-kinetic-badge], [data-kinetic-title], [data-kinetic-button])[data-state] {
	--_c: var(--kinetic-state-success);
}

:is(
		[data-kinetic-badge],
		[data-kinetic-title],
		[data-kinetic-button]
	)[data-state="loading"] {
	--_c: var(--kinetic-state-loading);
}

:is(
		[data-kinetic-badge],
		[data-kinetic-title],
		[data-kinetic-button]
	)[data-state="error"] {
	--_c: var(--kinetic-state-error);
}

:is(
		[data-kinetic-badge],
		[data-kinetic-title],
		[data-kinetic-button]
	)[data-state="warning"] {
	--_c: var(--kinetic-state-warning);
}

:is(
		[data-kinetic-badge],
		[data-kinetic-title],
		[data-kinetic-button]
	)[data-state="info"] {
	--_c: var(--kinetic-state-info);
}

:is(
		[data-kinetic-badge],
		[data-kinetic-title],
		[data-kinetic-button]
	)[data-state="action"] {
	--_c: var(--kinetic-state-action);
}

:is([data-kinetic-badge], [data-kinetic-title])[data-state] {
	--kinetic-tone: var(--_c);
	--kinetic-tone-bg: color-mix(in oklch, var(--_c) 20%, transparent);
}

/* --------------------------------- Content -------------------------------- */

[data-kinetic-content] {
	position: absolute;
	left: 0;
	z-index: 10;
	width: 100%;
	pointer-events: none;
	opacity: var(--_co, 0);
}

[data-kinetic-content]:not([data-visible="true"]) {
	content-visibility: hidden;
}

[data-kinetic-toast][data-ready="true"] [data-kinetic-content] {
	transition: opacity calc(var(--kinetic-duration) * 0.08) ease
		calc(var(--kinetic-duration) * 0.04);
}

[data-kinetic-content][data-edge="top"] {
	top: 0;
}

[data-kinetic-content][data-edge="bottom"] {
	top: var(--kinetic-height);
}

[data-kinetic-content][data-visible="true"] {
	pointer-events: auto;
}

[data-kinetic-toast][data-ready="true"]
	[data-kinetic-content][data-visible="true"] {
	transition: opacity calc(var(--kinetic-duration) * 0.6) ease
		calc(var(--kinetic-duration) * 0.3);
}

[data-kinetic-description] {
	width: 100%;
	text-align: left;
	padding: 1rem;
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--kinetic-toast-fg-muted);
	contain: layout style paint;
	content-visibility: auto;
}

/* --------------------------------- Button --------------------------------- */

[data-kinetic-button] {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 1.75rem;
	padding: 0 0.625rem;
	margin-top: 0.75rem;
	border-radius: 9999px;
	border: 0;
	font-size: 0.75rem;
	font-weight: 500;
	cursor: pointer;
	color: var(--kinetic-btn-color, currentColor);
	background-color: var(--kinetic-btn-bg, transparent);
	transition: background-color 150ms ease;
}

[data-kinetic-button]:hover {
	background-color: var(--kinetic-btn-bg-hover, transparent);
}

[data-kinetic-button][data-state] {
	--kinetic-btn-color: var(--_c);
	--kinetic-btn-bg: color-mix(in oklch, var(--_c) 15%, transparent);
	--kinetic-btn-bg-hover: color-mix(in oklch, var(--_c) 25%, transparent);
}

/* -------------------------------- Animations ------------------------------ */

[data-kinetic-icon="spin"] {
	animation: kinetic-spin 1s linear infinite;
}

@keyframes kinetic-spin {
	to {
		transform: rotate(360deg);
	}
}

@keyframes kinetic-header-enter {
	from {
		opacity: 0;
		filter: blur(6px);
	}
	to {
		opacity: 1;
		filter: blur(0px);
	}
}

@keyframes kinetic-header-exit {
	from {
		opacity: 1;
		filter: blur(0px);
	}
	to {
		opacity: 0;
		filter: blur(6px);
	}
}

/* -------------------------------- Viewports ------------------------------- */

[data-kinetic-viewport] {
	position: fixed;
	z-index: 9999;
	display: flex;
	gap: 0.75rem;
	padding: 0.75rem;
	pointer-events: none;
	max-width: calc(100vw - 1.5rem);
	contain: layout style;
}

[data-kinetic-viewport][data-position^="top"]
	[data-kinetic-toast]:not([data-ready="true"]) {
	margin-bottom: calc(-1 * (var(--kinetic-height) + 0.75rem));
}

[data-kinetic-viewport][data-position^="bottom"]
	[data-kinetic-toast]:not([data-ready="true"]) {
	margin-top: calc(-1 * (var(--kinetic-height) + 0.75rem));
}

/* Vertical edge */
[data-kinetic-viewport][data-position^="top"] {
	top: 0;
	flex-direction: column-reverse;
}

[data-kinetic-viewport][data-position^="bottom"] {
	bottom: 0;
	flex-direction: column;
}

/* Horizontal alignment */
[data-kinetic-viewport][data-position$="left"] {
	left: 0;
	align-items: flex-start;
}

[data-kinetic-viewport][data-position$="right"] {
	right: 0;
	align-items: flex-end;
}

[data-kinetic-viewport][data-position$="center"] {
	left: 50%;
	transform: translateX(-50%);
	align-items: center;
}

/* ------------------------------ Navigation -------------------------------- */

[data-kinetic-nav] {
	display: flex;
	align-items: center;
	gap: 0.125rem;
	margin-left: auto;
	flex-shrink: 0;
	color: currentColor;
	pointer-events: auto;
	user-select: none;
}

/*
 * When the close button is rendered, the X sits absolutely at the toast's
 * top-right corner and would otherwise overlap the trailing chevron of the
 * nav cluster. Push the nav left by the close button's width (accounting
 * for the header's 0.5rem right padding) so they no longer collide.
 */
[data-kinetic-toast]:has([data-kinetic-close]) [data-kinetic-nav] {
	margin-right: calc(var(--kinetic-height) - 0.5rem);
}

[data-kinetic-nav] button {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 1.5rem;
	height: 1.5rem;
	padding: 0;
	border: 0;
	border-radius: 9999px;
	background: transparent;
	cursor: pointer;
	color: inherit;
}

[data-kinetic-nav] button:not(:disabled):hover {
	background-color: color-mix(in oklab, currentColor 12%, transparent);
}

[data-kinetic-nav] button:disabled {
	opacity: 0.3;
	cursor: default;
}

/* ----------------------------- Close Button ------------------------------ */

[data-kinetic-close] {
	position: absolute;
	top: 0;
	right: 0;
	z-index: 30;
	display: flex;
	align-items: center;
	justify-content: center;
	width: var(--kinetic-height);
	height: var(--kinetic-height);
	padding: 0;
	border: 0;
	background: transparent;
	cursor: pointer;
	pointer-events: auto;
	color: currentColor;
	opacity: 0;
	transition: opacity 150ms ease;
}

[data-kinetic-toast]:hover [data-kinetic-close],
[data-kinetic-close]:focus-visible {
	opacity: 0.65;
}

[data-kinetic-close]:hover {
	opacity: 1;
}

@media (prefers-reduced-motion: no-preference) {
	[data-kinetic-toast][data-ready="true"]:hover,
	[data-kinetic-toast][data-ready="true"][data-exiting="true"] {
		will-change: transform, opacity, height;
	}
}

@media (prefers-reduced-motion: reduce) {
	[data-kinetic-viewport],
	[data-kinetic-viewport] *,
	[data-kinetic-viewport] *::before,
	[data-kinetic-viewport] *::after {
		animation-duration: 0.01ms;
		animation-iteration-count: 1;
		transition-duration: 0.01ms;
	}
}
